begin;

insert into public.auth_permissions(code,name,description,resource,action,module_code,permission_type,sort_order,active)values
('financial.settlement.create','إنشاء تسوية مزود','إنشاء تسوية من بنود clearing منشورة.','financial.settlement','create','accountant_app','action',180,true),
('financial.settlement.submit','إرسال تسوية مزود','إرسال التسوية للمراجعة.','financial.settlement','submit','accountant_app','action',181,true),
('financial.settlement.confirm','تأكيد تسوية مزود','تأكيد التسوية قبل الترحيل.','financial.settlement','confirm','accountant_app','action',182,true),
('financial.settlement.post','ترحيل تسوية مزود','ترحيل clearing إلى destination ورسوم المزود.','financial.settlement','post','accountant_app','action',183,true)
on conflict(code)do update set name=excluded.name,description=excluded.description,resource=excluded.resource,action=excluded.action,module_code=excluded.module_code,permission_type=excluded.permission_type,sort_order=excluded.sort_order,active=true,updated_at=now();

alter table public.financial_payment_methods add column settlement_mode text not null default'direct',add constraint financial_payment_methods_settlement_mode_check check(settlement_mode in('direct','clearing'));
create table public.financial_payment_method_settlement_configs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete restrict,payment_method_id uuid not null,clearing_account_id uuid not null,clearing_journal_id uuid not null,fee_account_id uuid,destination_type text not null default'bank',branch_id uuid,is_active boolean not null default true,created_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(payment_method_id,tenant_id)references public.financial_payment_methods(id,tenant_id)on delete restrict,foreign key(clearing_account_id,tenant_id)references public.account_accounts(id,tenant_id)on delete restrict,foreign key(clearing_journal_id,tenant_id)references public.account_journals(id,tenant_id)on delete restrict,foreign key(fee_account_id,tenant_id)references public.account_accounts(id,tenant_id)on delete restrict,foreign key(branch_id,tenant_id)references public.branches(id,tenant_id)on delete restrict,foreign key(created_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,unique(tenant_id,payment_method_id),unique(id,tenant_id),check(destination_type in('bank','wallet')));

create table public.financial_settlement_sequences(tenant_id uuid not null references public.tenants(id)on delete cascade,sequence_year int not null,next_number bigint not null default 1,updated_at timestamptz not null default now(),primary key(tenant_id,sequence_year),check(next_number>0));
create table public.financial_settlements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete restrict,settlement_number text not null,settlement_type text not null default'provider_batch',payment_method_id uuid not null,settlement_config_id uuid not null,money_destination_id uuid not null,gross_amount numeric(18,2)not null,fees_amount numeric(18,2)not null default 0,net_amount numeric(18,2)not null,currency_code text not null,branch_id uuid,reference text,external_reference text,settlement_date date not null,status text not null default'draft',accounting_state text not null default'unposted',created_by uuid not null,submitted_by uuid,submitted_at timestamptz,confirmed_by uuid,confirmed_at timestamptz,posted_by uuid,posted_at timestamptz,rejected_by uuid,rejected_at timestamptz,rejection_reason text,idempotency_key text not null,request_fingerprint text not null,posting_idempotency_key text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(payment_method_id,tenant_id)references public.financial_payment_methods(id,tenant_id)on delete restrict,foreign key(settlement_config_id,tenant_id)references public.financial_payment_method_settlement_configs(id,tenant_id)on delete restrict,foreign key(money_destination_id,tenant_id)references public.money_destinations(id,tenant_id)on delete restrict,foreign key(branch_id,tenant_id)references public.branches(id,tenant_id)on delete restrict,foreign key(created_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,foreign key(submitted_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,foreign key(confirmed_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,foreign key(posted_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,foreign key(rejected_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,unique(tenant_id,settlement_number),unique(tenant_id,idempotency_key),unique(tenant_id,posting_idempotency_key),unique(id,tenant_id),check(settlement_number~'^STL-[0-9]{4}-[0-9]{6,}$'),check(settlement_type='provider_batch'),check(gross_amount>0 and fees_amount>=0 and net_amount>0 and gross_amount=net_amount+fees_amount),check(currency_code~'^[A-Z]{3}$'),check(status in('draft','submitted','confirmed','rejected')),check(accounting_state in('unposted','posted','reversed')),check(request_fingerprint~'^[0-9a-f]{64}$'));
create table public.financial_settlement_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,settlement_id uuid not null,source_payment_id uuid not null,source_clearing_line_id uuid not null,gross_amount numeric(18,2)not null,created_at timestamptz not null default now(),foreign key(settlement_id,tenant_id)references public.financial_settlements(id,tenant_id)on delete restrict,foreign key(source_payment_id,tenant_id)references public.financial_payments(id,tenant_id)on delete restrict,foreign key(source_clearing_line_id,tenant_id)references public.account_move_lines(id,tenant_id)on delete restrict,unique(tenant_id,settlement_id,source_clearing_line_id),check(gross_amount>0));
create table public.financial_settlement_accounting_links(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,settlement_id uuid not null,account_move_id uuid not null,created_by uuid not null,created_at timestamptz not null default now(),foreign key(settlement_id,tenant_id)references public.financial_settlements(id,tenant_id)on delete restrict,foreign key(account_move_id,tenant_id)references public.account_moves(id,tenant_id)on delete restrict,foreign key(created_by,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,unique(tenant_id,settlement_id),unique(tenant_id,account_move_id));
create table public.financial_settlement_item_reconcile_links(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,settlement_item_id uuid not null,partial_reconcile_id uuid not null references public.account_partial_reconcile(id)on delete restrict,settlement_clearing_line_id uuid not null,created_at timestamptz not null default now(),foreign key(settlement_item_id)references public.financial_settlement_items(id)on delete restrict,foreign key(settlement_clearing_line_id,tenant_id)references public.account_move_lines(id,tenant_id)on delete restrict,unique(tenant_id,settlement_item_id),unique(tenant_id,partial_reconcile_id));
create table public.financial_settlement_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,settlement_id uuid not null,event_type text not null,from_status text,to_status text,actor_user_id uuid not null,reason text,metadata jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(settlement_id,tenant_id)references public.financial_settlements(id,tenant_id)on delete restrict,foreign key(actor_user_id,tenant_id)references public.tenant_users(id,tenant_id)on delete restrict,check(event_type in('created','submitted','confirmed','posted','rejected','accounting_reversed')));

create or replace function public.next_financial_settlement_number(p_tenant uuid)returns text language plpgsql security definer set search_path=pg_catalog,public as $$declare y int:=extract(year from current_date)::int;n bigint;begin insert into public.financial_settlement_sequences values(p_tenant,y,2,now())on conflict(tenant_id,sequence_year)do update set next_number=public.financial_settlement_sequences.next_number+1,updated_at=now()returning next_number-1 into n;return'STL-'||y||'-'||lpad(n::text,6,'0');end$$;

create or replace function public.configure_payment_method_settlement(p_tenant uuid,p_method uuid,p_clearing_account uuid,p_clearing_journal uuid,p_fee_account uuid default null,p_destination_type text default'bank',p_branch uuid default null,p_active boolean default true)returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$declare actor uuid:=public.current_tenant_user_id();saved uuid;begin perform public.assert_financial_authorized(p_tenant,'financial.payment_method.manage',null,null,p_branch,true);if not exists(select 1 from public.financial_payment_methods where id=p_method and tenant_id=p_tenant and method_type in('card','other')and is_active)then raise exception using errcode='23514',message='CLEARING_PAYMENT_METHOD_INVALID';end if;if not exists(select 1 from public.account_accounts where id=p_clearing_account and tenant_id=p_tenant and active and is_posting and open_item_reconcile and canonical_account_type in('current_asset','receivable')and reporting_category='other_receivables')then raise exception using errcode='23514',message='CLEARING_ACCOUNT_SEMANTICS_INVALID';end if;if not exists(select 1 from public.account_journals where id=p_clearing_journal and tenant_id=p_tenant and is_active and default_account_id=p_clearing_account)then raise exception using errcode='23514',message='CLEARING_JOURNAL_INVALID';end if;if p_fee_account is not null and not exists(select 1 from public.account_accounts where id=p_fee_account and tenant_id=p_tenant and active and is_posting and canonical_account_type='expense'and reporting_category='operating_expenses')then raise exception using errcode='23514',message='PROCESSING_FEE_ACCOUNT_INVALID';end if;insert into public.financial_payment_method_settlement_configs(tenant_id,payment_method_id,clearing_account_id,clearing_journal_id,fee_account_id,destination_type,branch_id,is_active,created_by)values(p_tenant,p_method,p_clearing_account,p_clearing_journal,p_fee_account,p_destination_type,p_branch,coalesce(p_active,true),actor)on conflict(tenant_id,payment_method_id)do update set clearing_account_id=excluded.clearing_account_id,clearing_journal_id=excluded.clearing_journal_id,fee_account_id=excluded.fee_account_id,destination_type=excluded.destination_type,branch_id=excluded.branch_id,is_active=excluded.is_active,updated_at=now()returning id into saved;update public.financial_payment_methods set settlement_mode='clearing'where id=p_method and tenant_id=p_tenant;return saved;end$$;

create or replace function public.create_financial_payment_posting_move(p_tenant_id uuid,p_payment_id uuid,p_payment_number text,p_direction text,p_amount numeric,p_currency_code text,p_partner_id uuid,p_purpose text,p_destination_name text,p_destination_account_id uuid,p_counterpart_account_id uuid,p_journal_id uuid,p_branch_id uuid,p_actor_id uuid,p_destination_side text,p_counterpart_side text,p_source_app text,p_source_model text,p_source_id text)returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$declare mid uuid:=gen_random_uuid();dl uuid:=gen_random_uuid();cl uuid:=gen_random_uuid();clearing boolean:=exists(select 1 from public.financial_payments p join public.financial_payment_method_settlement_configs c on c.payment_method_id=p.payment_method_id and c.tenant_id=p.tenant_id and c.is_active where p.id=p_payment_id and p.tenant_id=p_tenant_id and c.clearing_account_id=p_destination_account_id and c.clearing_journal_id=p_journal_id);begin if current_setting('app.financial_payment_posting_contract',true)is distinct from p_payment_id::text then raise exception using errcode='42501',message='PAYMENT_MOVE_CONSTRUCTION_REQUIRES_POSTING_CONTRACT';end if;if p_destination_side=p_counterpart_side then raise exception using errcode='23514',message='PAYMENT_POSTING_SIDES_INVALID';end if;if not exists(select 1 from public.account_accounts where id=p_destination_account_id and tenant_id=p_tenant_id and active and is_posting and((clearing and open_item_reconcile)or(not clearing and account_origin='resource')))or not exists(select 1 from public.account_accounts where id=p_counterpart_account_id and tenant_id=p_tenant_id and active and is_posting and open_item_reconcile)or not exists(select 1 from public.account_journals where id=p_journal_id and tenant_id=p_tenant_id and is_active and default_account_id=p_destination_account_id)then raise exception using errcode='23514',message='PAYMENT_POSTING_ACCOUNT_OR_JOURNAL_INVALID';end if;insert into public.account_moves(id,tenant_id,branch_id,journal_id,name,move_type,partner_id,invoice_date,date,amount_total,state,ref,notes,pay_method,currency_code,created_by)values(mid,p_tenant_id,p_branch_id,p_journal_id,'PAYMENT-'||p_payment_number,case when clearing then'journal'when p_direction='inbound'then'cash_in'else'cash_out'end,p_partner_id,current_date,now(),p_amount,'posted','financial_payment:'||p_payment_id,case when clearing then'clearing_required'else'direct_settlement'end,'canonical_payment',p_currency_code,p_actor_id);insert into public.account_move_lines(id,tenant_id,move_id,account_id,partner_id,label,quantity,unit_price,debit,credit,line_type,is_reconciled,amount_residual,amount_residual_currency,parent_state,currency_code,created_by)values(dl,p_tenant_id,mid,p_destination_account_id,null,p_destination_name||' — '||p_payment_number,1,p_amount,case when p_destination_side='debit'then p_amount else 0 end,case when p_destination_side='credit'then p_amount else 0 end,case when clearing then'open_item'else'liquidity'end,not clearing,case when clearing then p_amount else 0 end,case when clearing then p_amount else 0 end,'posted',p_currency_code,p_actor_id),(cl,p_tenant_id,mid,p_counterpart_account_id,p_partner_id,p_purpose||' — '||p_payment_number,1,p_amount,case when p_counterpart_side='debit'then p_amount else 0 end,case when p_counterpart_side='credit'then p_amount else 0 end,'open_item',false,p_amount,p_amount,'posted',p_currency_code,p_actor_id);perform public.accounting_assert_move_balanced(mid);return mid;end$$;

create or replace function public.post_financial_payment(p_tenant_id uuid,p_payment_id uuid,p_payment_purpose text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare p public.financial_payments%rowtype;purpose public.financial_payment_purposes%rowtype;m public.financial_payment_methods%rowtype;cfg public.financial_payment_method_settlement_configs%rowtype;dst record;counter uuid;actor uuid:=public.current_tenant_user_id();mid uuid;dname text;da uuid;jid uuid;begin perform pg_advisory_xact_lock(hashtextextended('financial_payment_post:'||p_tenant_id||':'||p_payment_id,0));select*into p from public.financial_payments where id=p_payment_id and tenant_id=p_tenant_id for update;if not found then raise exception using errcode='P0002',message='FINANCIAL_PAYMENT_NOT_FOUND';end if;perform public.assert_financial_authorized(p_tenant_id,'financial.payment.post',null,null,p.branch_id,p.status='confirmed');if p.accounting_state='posted'then if p.payment_purpose is distinct from p_payment_purpose then raise exception using errcode='23514',message='FINANCIAL_PAYMENT_ALREADY_POSTED_WITH_DIFFERENT_PURPOSE';end if;return jsonb_build_object('payment_id',p.id,'account_move_id',(select account_move_id from public.financial_payment_accounting_links where payment_id=p.id and entry_type='posting'),'idempotent_replay',true);end if;select*into purpose from public.financial_payment_purposes where code=p_payment_purpose and is_active;if not found or purpose.direction<>p.direction then raise exception using errcode='23514',message='FINANCIAL_PAYMENT_PURPOSE_INVALID';end if;select*into m from public.financial_payment_methods where id=p.payment_method_id and tenant_id=p_tenant_id and is_active;if m.settlement_mode='clearing'then select*into cfg from public.financial_payment_method_settlement_configs where payment_method_id=m.id and tenant_id=p_tenant_id and is_active;if not found or(cfg.branch_id is not null and cfg.branch_id is distinct from p.branch_id)or p.direction<>'inbound'then raise exception using errcode='23514',message='PAYMENT_CLEARING_CONFIGURATION_INVALID_OR_UNSUPPORTED_DIRECTION';end if;perform public.assert_financial_authorized(p_tenant_id,'financial.payment.post',cfg.clearing_account_id,'reconcile',p.branch_id,true);dname:='Clearing — '||m.name;da:=cfg.clearing_account_id;jid:=cfg.clearing_journal_id;else if p.money_destination_id is null then raise exception using errcode='23514',message='POSTABLE_FINANCIAL_PAYMENT_REQUIRES_DESTINATION';end if;select*into dst from public.resolve_money_destination_for_action(p_tenant_id,p.money_destination_id,'financial.payment.post','confirm',p.branch_id,array(select destination_type from public.financial_payment_method_destination_types where method_type=m.method_type));dname:=dst.destination_name;da:=dst.ledger_account_id;jid:=dst.journal_id;end if;counter:=public.resolve_functional_account(p_tenant_id,purpose.counterpart_functional_role,p.branch_id);perform set_config('app.financial_payment_posting_contract',p.id::text,true);mid:=public.create_financial_payment_posting_move(p_tenant_id,p.id,p.payment_number,p.direction,p.amount,p.currency_code,p.partner_id,purpose.code,dname,da,counter,jid,p.branch_id,actor,purpose.destination_side,purpose.counterpart_side,p.source_app,p.source_model,p.source_id);insert into public.financial_payment_accounting_links(tenant_id,payment_id,account_move_id,entry_type,created_by)values(p_tenant_id,p.id,mid,'posting',actor);update public.financial_payments set accounting_state='posted',payment_purpose=purpose.code,posted_by=actor,posted_at=now()where id=p.id;insert into public.financial_payment_events(tenant_id,payment_id,event_type,from_status,to_status,actor_user_id,metadata)values(p_tenant_id,p.id,'posted','confirmed','confirmed',actor,jsonb_build_object('account_move_id',mid,'settlement_mode',m.settlement_mode));return jsonb_build_object('payment_id',p.id,'account_move_id',mid,'accounting_state','posted','settlement_mode',m.settlement_mode,'idempotent_replay',false);end$$;

create or replace function public.list_settleable_clearing_items(p_tenant uuid,p_method uuid,p_currency text default null,p_branch uuid default null)returns table(payment_id uuid,payment_number text,clearing_line_id uuid,residual_amount numeric,currency_code text,branch_id uuid,clearing_account_id uuid)language sql stable security definer set search_path=pg_catalog,public as $$select p.id,p.payment_number,l.id,l.amount_residual,l.currency_code,m.branch_id,l.account_id from public.financial_payments p join public.financial_payment_accounting_links pl on pl.payment_id=p.id and pl.tenant_id=p.tenant_id and pl.entry_type='posting'join public.account_moves m on m.id=pl.account_move_id and m.tenant_id=pl.tenant_id join public.financial_payment_method_settlement_configs c on c.payment_method_id=p.payment_method_id and c.tenant_id=p.tenant_id and c.is_active join public.account_move_lines l on l.move_id=m.id and l.tenant_id=m.tenant_id and l.account_id=c.clearing_account_id where p.tenant_id=p_tenant and p.payment_method_id=p_method and p.accounting_state='posted'and m.state='posted'and l.parent_state='posted'and l.amount_residual>0 and(p_currency is null or l.currency_code=upper(p_currency))and(p_branch is null or m.branch_id is not distinct from p_branch)and public.can_perform_financial_action(p_tenant,'financial.settlement.create',l.account_id,'reconcile',m.branch_id,true)order by m.date,l.id$$;

create or replace function public.get_financial_settlement_eligibility(p_tenant uuid,p_method uuid,p_items jsonb,p_destination uuid,p_gross numeric,p_fees numeric,p_net numeric,p_currency text,p_branch uuid default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare available numeric;blocks jsonb:='[]';cfg public.financial_payment_method_settlement_configs%rowtype;begin if public.current_tenant_id()<>p_tenant then raise exception using errcode='42501',message='SETTLEMENT_TENANT_ACCESS_DENIED';end if;select*into cfg from public.financial_payment_method_settlement_configs where tenant_id=p_tenant and payment_method_id=p_method and is_active;if not found then blocks:=blocks||'"SETTLEMENT_CONFIG_MISSING"';end if;select coalesce(sum((x->>'amount')::numeric),0)into available from jsonb_array_elements(coalesce(p_items,'[]'))x;if p_gross is null or p_gross<>available then blocks:=blocks||'"SETTLEMENT_ITEMS_GROSS_MISMATCH"';end if;if p_gross<>p_net+p_fees then blocks:=blocks||'"SETTLEMENT_AMOUNT_MISMATCH"';end if;if not public.has_permission('financial.settlement.create',p_tenant)then blocks:=blocks||'"SETTLEMENT_AUTHORIZATION_DENIED"';end if;return jsonb_build_object('eligible',jsonb_array_length(blocks)=0,'selected_gross',available,'gross_amount',p_gross,'fees_amount',p_fees,'net_amount',p_net,'currency_code',upper(p_currency),'destination_id',p_destination,'payment_method_id',p_method,'blockers',blocks);end$$;

create or replace function public.create_financial_settlement(p_tenant uuid,p_method uuid,p_destination uuid,p_items jsonb,p_gross numeric,p_fees numeric,p_net numeric,p_currency text,p_date date,p_idempotency text,p_branch uuid default null,p_reference text default null,p_external_reference text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare cfg public.financial_payment_method_settlement_configs%rowtype;existing public.financial_settlements%rowtype;actor uuid:=public.current_tenant_user_id();fp text;sid uuid:=gen_random_uuid();num text;x jsonb;l record;sum_amount numeric:=0;begin perform public.assert_financial_authorized(p_tenant,'financial.settlement.create',null,null,p_branch,true);if jsonb_typeof(p_items)<>'array'or jsonb_array_length(p_items)=0 or p_gross<=0 or p_fees<0 or p_net<=0 or p_gross<>p_net+p_fees then raise exception using errcode='23514',message='SETTLEMENT_AMOUNT_MISMATCH';end if;select*into cfg from public.financial_payment_method_settlement_configs where tenant_id=p_tenant and payment_method_id=p_method and is_active for share;if not found or(cfg.branch_id is not null and cfg.branch_id is distinct from p_branch)then raise exception using errcode='23514',message='SETTLEMENT_CONFIG_INVALID';end if;perform public.assert_financial_authorized(p_tenant,'financial.settlement.create',cfg.clearing_account_id,'reconcile',p_branch,true);perform public.resolve_money_destination_for_action(p_tenant,p_destination,'financial.settlement.create','reconcile',p_branch,array[cfg.destination_type]);fp:=encode(extensions.digest(jsonb_build_object('method',p_method,'destination',p_destination,'items',p_items,'gross',p_gross,'fees',p_fees,'net',p_net,'currency',upper(p_currency),'date',p_date,'branch',p_branch,'reference',p_reference,'external',p_external_reference)::text,'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('settlement:create:'||p_tenant||':'||btrim(p_idempotency),0));select*into existing from public.financial_settlements where tenant_id=p_tenant and idempotency_key=btrim(p_idempotency);if found then if existing.request_fingerprint<>fp then raise exception using errcode='23505',message='SETTLEMENT_IDEMPOTENCY_PAYLOAD_MISMATCH';end if;return jsonb_build_object('settlement_id',existing.id,'settlement_number',existing.settlement_number,'idempotent_replay',true);end if;for x in select*from jsonb_array_elements(p_items)loop select q.*into l from public.list_settleable_clearing_items(p_tenant,p_method,upper(p_currency),p_branch)q where q.clearing_line_id=(x->>'clearing_line_id')::uuid;if not found or(x->>'amount')::numeric<=0 or(x->>'amount')::numeric>l.residual_amount then raise exception using errcode='23514',message='SETTLEMENT_ITEM_NOT_ELIGIBLE_OR_EXCEEDS_RESIDUAL';end if;sum_amount:=sum_amount+(x->>'amount')::numeric;end loop;if sum_amount<>p_gross then raise exception using errcode='23514',message='SETTLEMENT_ITEMS_GROSS_MISMATCH';end if;if p_fees>0 and cfg.fee_account_id is null then raise exception using errcode='23514',message='SETTLEMENT_FEE_ACCOUNT_REQUIRED';end if;num:=public.next_financial_settlement_number(p_tenant);insert into public.financial_settlements(id,tenant_id,settlement_number,payment_method_id,settlement_config_id,money_destination_id,gross_amount,fees_amount,net_amount,currency_code,branch_id,reference,external_reference,settlement_date,created_by,idempotency_key,request_fingerprint)values(sid,p_tenant,num,p_method,cfg.id,p_destination,p_gross,p_fees,p_net,upper(p_currency),p_branch,p_reference,p_external_reference,coalesce(p_date,current_date),actor,btrim(p_idempotency),fp);for x in select*from jsonb_array_elements(p_items)loop select q.*into l from public.list_settleable_clearing_items(p_tenant,p_method,upper(p_currency),p_branch)q where q.clearing_line_id=(x->>'clearing_line_id')::uuid;insert into public.financial_settlement_items(tenant_id,settlement_id,source_payment_id,source_clearing_line_id,gross_amount)values(p_tenant,sid,l.payment_id,l.clearing_line_id,(x->>'amount')::numeric);end loop;insert into public.financial_settlement_events(tenant_id,settlement_id,event_type,to_status,actor_user_id,metadata)values(p_tenant,sid,'created','draft',actor,jsonb_build_object('item_count',jsonb_array_length(p_items),'gross',p_gross));return jsonb_build_object('settlement_id',sid,'settlement_number',num,'status','draft','idempotent_replay',false);end$$;

create or replace function public.transition_financial_settlement(p_tenant uuid,p_settlement uuid,p_action text,p_reason text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s public.financial_settlements%rowtype;actor uuid:=public.current_tenant_user_id();n text;perm text;begin select*into s from public.financial_settlements where id=p_settlement and tenant_id=p_tenant for update;if not found then raise exception using errcode='P0002',message='FINANCIAL_SETTLEMENT_NOT_FOUND';end if;if p_action='submit'and s.status='draft'then n:='submitted';perm:='financial.settlement.submit';elsif p_action='confirm'and s.status='submitted'then n:='confirmed';perm:='financial.settlement.confirm';elsif p_action='reject'and s.status in('draft','submitted')then n:='rejected';perm:='financial.settlement.confirm';if nullif(btrim(coalesce(p_reason,'')),'')is null then raise exception using errcode='22023',message='SETTLEMENT_REJECTION_REASON_REQUIRED';end if;else raise exception using errcode='23514',message='SETTLEMENT_LIFECYCLE_INVALID';end if;perform public.assert_financial_authorized(p_tenant,perm,null,null,s.branch_id,true);perform set_config('app.financial_settlement_contract',s.id::text,true);if n='submitted'then update public.financial_settlements set status=n,submitted_by=actor,submitted_at=now(),updated_at=now()where id=s.id;elsif n='confirmed'then update public.financial_settlements set status=n,confirmed_by=actor,confirmed_at=now(),updated_at=now()where id=s.id;else update public.financial_settlements set status=n,rejected_by=actor,rejected_at=now(),rejection_reason=btrim(p_reason),updated_at=now()where id=s.id;end if;insert into public.financial_settlement_events(tenant_id,settlement_id,event_type,from_status,to_status,actor_user_id,reason)values(p_tenant,s.id,n,s.status,n,actor,p_reason);return jsonb_build_object('settlement_id',s.id,'status',n);end$$;
create or replace function public.submit_financial_settlement(p_tenant uuid,p_settlement uuid)returns jsonb language sql security definer set search_path=pg_catalog,public as $$select public.transition_financial_settlement(p_tenant,p_settlement,'submit')$$;
create or replace function public.confirm_financial_settlement(p_tenant uuid,p_settlement uuid)returns jsonb language sql security definer set search_path=pg_catalog,public as $$select public.transition_financial_settlement(p_tenant,p_settlement,'confirm')$$;

create or replace function public.post_financial_settlement(p_tenant uuid,p_settlement uuid,p_idempotency text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s public.financial_settlements%rowtype;cfg public.financial_payment_method_settlement_configs%rowtype;dst record;actor uuid:=public.current_tenant_user_id();mid uuid:=gen_random_uuid();clearline uuid:=gen_random_uuid();fee_line uuid:=gen_random_uuid();cash_line uuid:=gen_random_uuid();i public.financial_settlement_items%rowtype;src public.account_move_lines%rowtype;partial uuid;remaining numeric:=0;begin perform pg_advisory_xact_lock(hashtextextended('settlement:post:'||p_tenant||':'||p_settlement,0));select*into s from public.financial_settlements where id=p_settlement and tenant_id=p_tenant for update;if not found then raise exception using errcode='P0002',message='FINANCIAL_SETTLEMENT_NOT_FOUND';end if;if s.accounting_state='posted'then if s.posting_idempotency_key<>btrim(p_idempotency)then raise exception using errcode='23505',message='SETTLEMENT_POST_IDEMPOTENCY_MISMATCH';end if;return jsonb_build_object('settlement_id',s.id,'account_move_id',(select account_move_id from public.financial_settlement_accounting_links where settlement_id=s.id),'idempotent_replay',true);end if;perform public.assert_financial_authorized(p_tenant,'financial.settlement.post',null,null,s.branch_id,s.status='confirmed'and s.accounting_state='unposted');select*into cfg from public.financial_payment_method_settlement_configs where id=s.settlement_config_id and tenant_id=p_tenant and is_active;perform public.assert_financial_authorized(p_tenant,'financial.settlement.post',cfg.clearing_account_id,'reconcile',s.branch_id,true);select*into dst from public.resolve_money_destination_for_action(p_tenant,s.money_destination_id,'financial.settlement.post','reconcile',s.branch_id,array[cfg.destination_type]);for i in select*from public.financial_settlement_items where settlement_id=s.id order by source_clearing_line_id loop perform pg_advisory_xact_lock(hashtextextended('clearing-line:'||p_tenant||':'||i.source_clearing_line_id,0));select*into src from public.account_move_lines where id=i.source_clearing_line_id and tenant_id=p_tenant for update;if src.account_id<>cfg.clearing_account_id or src.currency_code<>s.currency_code or src.amount_residual<i.gross_amount then raise exception using errcode='23514',message='SETTLEMENT_SOURCE_RESIDUAL_CHANGED';end if;remaining:=remaining+i.gross_amount;end loop;if remaining<>s.gross_amount or s.gross_amount<>s.net_amount+s.fees_amount then raise exception using errcode='23514',message='SETTLEMENT_AMOUNT_MISMATCH';end if;insert into public.account_moves(id,tenant_id,branch_id,journal_id,name,move_type,invoice_date,date,amount_total,state,ref,notes,currency_code,created_by)values(mid,p_tenant,s.branch_id,dst.journal_id,'SETTLEMENT-'||s.settlement_number,s.settlement_type,s.settlement_date,s.settlement_date,s.gross_amount,'posted','financial_settlement:'||s.id,'Clearing to destination; no customer allocation',s.currency_code,actor);insert into public.account_move_lines(id,tenant_id,move_id,account_id,label,quantity,unit_price,debit,credit,line_type,is_reconciled,amount_residual,amount_residual_currency,parent_state,currency_code,created_by)values(cash_line,p_tenant,mid,dst.ledger_account_id,s.settlement_number||' net',1,s.net_amount,s.net_amount,0,'liquidity',true,0,0,'posted',s.currency_code,actor),(clearline,p_tenant,mid,cfg.clearing_account_id,s.settlement_number||' gross clearing',1,s.gross_amount,0,s.gross_amount,'open_item',false,s.gross_amount,s.gross_amount,'posted',s.currency_code,actor);if s.fees_amount>0 then insert into public.account_move_lines(id,tenant_id,move_id,account_id,label,quantity,unit_price,debit,credit,line_type,is_reconciled,amount_residual,amount_residual_currency,parent_state,currency_code,created_by)values(fee_line,p_tenant,mid,cfg.fee_account_id,s.settlement_number||' provider fees',1,s.fees_amount,s.fees_amount,0,'other',true,0,0,'posted',s.currency_code,actor);end if;perform public.accounting_assert_move_balanced(mid);for i in select*from public.financial_settlement_items where settlement_id=s.id order by source_clearing_line_id loop partial:=gen_random_uuid();insert into public.account_partial_reconcile(id,tenant_id,debit_move_id,credit_move_id,amount,max_date,created_by)values(partial,p_tenant,i.source_clearing_line_id,clearline,i.gross_amount,s.settlement_date,actor);insert into public.financial_settlement_item_reconcile_links(tenant_id,settlement_item_id,partial_reconcile_id,settlement_clearing_line_id)values(p_tenant,i.id,partial,clearline);end loop;insert into public.financial_settlement_accounting_links(tenant_id,settlement_id,account_move_id,created_by)values(p_tenant,s.id,mid,actor);update public.financial_settlements set accounting_state='posted',posted_by=actor,posted_at=now(),posting_idempotency_key=btrim(p_idempotency),updated_at=now()where id=s.id;insert into public.financial_settlement_events(tenant_id,settlement_id,event_type,from_status,to_status,actor_user_id,metadata)values(p_tenant,s.id,'posted',s.status,s.status,actor,jsonb_build_object('account_move_id',mid,'gross',s.gross_amount,'fees',s.fees_amount,'net',s.net_amount));return jsonb_build_object('settlement_id',s.id,'account_move_id',mid,'accounting_state','posted','idempotent_replay',false);end$$;

create or replace function public.guard_financial_settlement_immutable()returns trigger language plpgsql set search_path=pg_catalog,public as $$begin if tg_op='DELETE'or old.accounting_state='posted'or(new.accounting_state is distinct from old.accounting_state and current_setting('app.financial_settlement_contract',true)is distinct from old.id::text)then raise exception using errcode='42501',message='FINANCIAL_SETTLEMENT_IMMUTABLE_OR_CONTRACT_REQUIRED';end if;return new;end$$;
create trigger financial_settlement_guard before update or delete on public.financial_settlements for each row execute function public.guard_financial_settlement_immutable();
create or replace function public.guard_financial_settlement_immutable()returns trigger language plpgsql set search_path=pg_catalog,public as $$begin if tg_op='DELETE'or old.accounting_state='posted'then raise exception using errcode='42501',message='FINANCIAL_SETTLEMENT_IMMUTABLE';end if;return new;end$$;

alter table public.financial_payment_method_settlement_configs enable row level security;alter table public.financial_settlements enable row level security;alter table public.financial_settlement_items enable row level security;alter table public.financial_settlement_accounting_links enable row level security;alter table public.financial_settlement_item_reconcile_links enable row level security;alter table public.financial_settlement_events enable row level security;
revoke all on public.financial_payment_method_settlement_configs,public.financial_settlements,public.financial_settlement_items,public.financial_settlement_accounting_links,public.financial_settlement_item_reconcile_links,public.financial_settlement_events from public,anon,authenticated;grant select on public.financial_payment_method_settlement_configs,public.financial_settlements,public.financial_settlement_items,public.financial_settlement_accounting_links,public.financial_settlement_item_reconcile_links,public.financial_settlement_events to authenticated;
create policy settlement_config_read on public.financial_payment_method_settlement_configs for select to authenticated using(tenant_id=public.current_tenant_id()and(public.has_permission('financial.payment_method.manage',tenant_id)or public.has_permission('financial.settlement.create',tenant_id)));
create policy settlements_read on public.financial_settlements for select to authenticated using(tenant_id=public.current_tenant_id()and(public.has_permission('financial.settlement.create',tenant_id)or public.has_permission('financial.settlement.confirm',tenant_id)or public.has_permission('financial.settlement.post',tenant_id)));
create policy settlement_items_read on public.financial_settlement_items for select to authenticated using(exists(select 1 from public.financial_settlements s where s.id=financial_settlement_items.settlement_id and s.tenant_id=financial_settlement_items.tenant_id));
create policy settlement_links_read on public.financial_settlement_accounting_links for select to authenticated using(exists(select 1 from public.financial_settlements s where s.id=financial_settlement_accounting_links.settlement_id and s.tenant_id=financial_settlement_accounting_links.tenant_id));
create policy settlement_reconcile_links_read on public.financial_settlement_item_reconcile_links for select to authenticated using(exists(select 1 from public.financial_settlement_items i join public.financial_settlements s on s.id=i.settlement_id and s.tenant_id=i.tenant_id where i.id=financial_settlement_item_reconcile_links.settlement_item_id and i.tenant_id=financial_settlement_item_reconcile_links.tenant_id));
create policy settlement_events_read on public.financial_settlement_events for select to authenticated using(exists(select 1 from public.financial_settlements s where s.id=financial_settlement_events.settlement_id and s.tenant_id=financial_settlement_events.tenant_id));

revoke all on function public.configure_payment_method_settlement(uuid,uuid,uuid,uuid,uuid,text,uuid,boolean),public.list_settleable_clearing_items(uuid,uuid,text,uuid),public.get_financial_settlement_eligibility(uuid,uuid,jsonb,uuid,numeric,numeric,numeric,text,uuid),public.create_financial_settlement(uuid,uuid,uuid,jsonb,numeric,numeric,numeric,text,date,text,uuid,text,text),public.transition_financial_settlement(uuid,uuid,text,text),public.submit_financial_settlement(uuid,uuid),public.confirm_financial_settlement(uuid,uuid),public.post_financial_settlement(uuid,uuid,text)from public,anon;grant execute on function public.configure_payment_method_settlement(uuid,uuid,uuid,uuid,uuid,text,uuid,boolean),public.list_settleable_clearing_items(uuid,uuid,text,uuid),public.get_financial_settlement_eligibility(uuid,uuid,jsonb,uuid,numeric,numeric,numeric,text,uuid),public.create_financial_settlement(uuid,uuid,uuid,jsonb,numeric,numeric,numeric,text,date,text,uuid,text,text),public.transition_financial_settlement(uuid,uuid,text,text),public.submit_financial_settlement(uuid,uuid),public.confirm_financial_settlement(uuid,uuid),public.post_financial_settlement(uuid,uuid,text)to authenticated;

comment on table public.financial_payment_method_settlement_configs is'Provider/method-specific clearing resource binding. Clearing is not a Money Destination.';comment on table public.financial_settlements is'Canonical provider settlement business event, distinct from Payment, Transfer, Refund, Reversal and customer allocation.';comment on function public.post_financial_settlement(uuid,uuid,text)is'Atomically moves gross clearing residual to net destination plus configured provider fee expense; destination journal is canonical and unexplained differences fail closed.';
commit;
